head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
scwin.vScrenID = "ULDSTF35500.xml";
scwin.clickIsuCd;
scwin.clickIsuKorAbbrv;
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_setElwInstNm_1 = function() {
    dts_ELW_INST_NM_1.DataID = "/CodeAction.do?method=listWrntCd&For=R";
    dts_ELW_INST_NM_1.Reset();
};
scwin.fn_list_sync = function() {
    if (MaxTab_01.getSelectedTabIndex() == 1) {
        /*var gLog = getObjectValue(chk_Log);
        if (gLog == 'Y') { 
        	gLog  = 'N';
        } else {
        	gLog  = 'Y';
        }*/
        var gLog = 'N';
        var url = "/ELWAllHoldAction.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listELWAllHold&inputMessageId=ELW_LP_ALL_HD_LIST_OUT";
        url += "&LIST_DD=" + $c.stf.getObjectValue(edt_TASK_DD);
        url += "&ISU_CD=" + $c.stf.getObjectValue(cmb_ELW_INST_NM_1);
        url += "&DELIST_DTEC_YN=" + gLog;
        dts_All_HD_LIST.DataID = encodeURI(url);
        dts_All_HD_LIST.reset();
        $c.cm.ShowWin(grd_All_HD_LIST);
    }
};
scwin.fn_setTaskDd = function() {
    var url = "/ELWAllHoldAction.do?method=calendarSearch&inputMessageId=ELW_LP_ALL_HD_TASK_DD_GET_OUT";
    dts_TASK_DD.DataID = encodeURI(url);
    dts_TASK_DD.reset();
};
scwin.fn_OpenDetail = async function(row) {
    if (row > 0) {
        //그리드에서 선택시
        scwin.clickIsuCd = dts_All_HD_LIST.getCellData(row, "ISU_CD");
        scwin.clickIsuKorAbbrv = dts_All_HD_LIST.getCellData(row, "ISU_KOR_ABBRV");
        await $c.frame.CreateDialogFrame("ULDSTF35503", "/lstmgt/ULDSTF35503.gfm", "개별종목보유수량조회", 100, 100, 905, 570 + 35, "");
    }
};
scwin.fn_ExcelDown = function() {
    if (MaxTab_01.getSelectedTabIndex() == 1) {
        //엑셀 로그 
        $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
        $c.data.downloadGridViewExcel(grd_All_HD_LIST, "전부보유리스트", "", "8");
    }
};
scwin.btn_Search_1_onclick = function() {
    scwin.fn_list_sync();
};
scwin.MaxTab_01_OnSelChanged = function(nIndex) {
    scwin.fn_list_sync();
};
scwin.cmb_ELW_INST_NM_1_OnSelChange = function() {
    scwin.fn_list_sync();
};
scwin.img_Excel_1_onclick = function() {
    scwin.fn_ExcelDown();
};
scwin.img_TASK_DD_onclick = function() {
    popUpCalendar2(edt_TASK_DD);
};
scwin.dts_All_HD_LIST_OnLoadError = function() {
    $c.stf.alert_error(dts_All_HD_LIST);
};
scwin.dts_TASK_DD_OnLoadError = function() {
    $c.stf.alert_error(dts_TASK_DD);
};
scwin.dts_ELW_INST_NM_1_OnLoadError = function() {
    $c.stf.alert_error(dts_ELW_INST_NM_1);
};
scwin.dts_All_HD_LIST_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page_1);
    $c.cm.CloseWin(rowcount, grd_All_HD_LIST);
};
scwin.grd_All_HD_LIST_OnDblClick = function(row, colid) {
    if (colid == "ISU_KOR_ABBRV") {
        scwin.fn_OpenDetail(row);
    }
};
scwin.btn_CrsTrd_onclick = async function() {
    await $c.frame.CreateDialogFrame("ULDSTF35501", "/lstmgt/ULDSTF35501.gfm", "자전거래조치", 150, 150, 720, 415 + 35, "");
};
scwin.btn_DlsPrc_onclick = async function() {
    await $c.frame.CreateDialogFrame("ULDSTF35502", "/lstmgt/ULDSTF35502.gfm", "상장폐지조치", 150, 150, 795, 420 + 35, "");
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.gform_onload = function() {
    MaxTab_01.setSelectedTabIndex(1);
    $c.stf.showObj(btn_CrsTrd, false);
    $c.stf.showObj(btn_DlsPrc, false);
    scwin.fn_setTaskDd();
    $c.cm.PanelToGroupBox(panel_Top_1);
    scwin.fn_setElwInstNm_1();
    scwin.fn_list_sync();
};
